-- LifeOS Migration 0027: Senegal-Focused Liver-Conscious Nutrition System
-- — seeded meal library
--
-- Generated content (checked by hand for the medical-safety rules in
-- the spec — no claim that any dish treats, cures, prevents, or
-- controls hepatitis B; every meal is an adaptation of a real,
-- well-known Senegalese/West African dish, never called "forbidden" or
-- criticized). Nutrition figures (calories/protein/carbs/fat/fiber/
-- sugar/sodium) are ESTIMATES based on typical ingredient composition —
-- LifeOS has no food-composition database to measure them precisely,
-- and the app must say so wherever they're displayed (Section 24: never
-- invent nutrition data as if it were measured fact).
--
-- Idempotent: only inserts a meal whose name_en doesn't already exist
-- (meals has no natural unique key otherwise), so re-running this file
-- is a no-op.

insert into meals (name_en, name_fr, description_en, description_fr, cuisine, meal_type, serving_size_en, serving_size_fr, ingredients, preparation_en, preparation_fr, liver_conscious_preparation, foods_to_reduce, substitutions, calories_kcal, protein_g, carbs_g, fat_g, fiber_g, sugar_g, sodium_mg, rating, rating_reason_en, rating_reason_fr, tags)
select v.name_en, v.name_fr, v.description_en, v.description_fr, v.cuisine, v.meal_type, v.serving_size_en, v.serving_size_fr, v.ingredients, v.preparation_en, v.preparation_fr, v.liver_conscious_preparation, v.foods_to_reduce, v.substitutions, v.calories_kcal, v.protein_g, v.carbs_g, v.fat_g, v.fiber_g, v.sugar_g, v.sodium_mg, v.rating, v.rating_reason_en, v.rating_reason_fr, v.tags
from (values
  ('Ceebu Jën', 'Ceebu Jën (Thiéboudienne)', 'Senegal''s national dish: fish, rice, and vegetables simmered together.', 'Le plat national du Sénégal : poisson, riz et légumes mijotés ensemble.', 'senegalese_west_african', 'lunch', '1 plate (~450 g)', '1 assiette (~450 g)', '[{"en":"Fish (e.g. grouper or similar)","fr":"Poisson (ex. mérou ou similaire)"},{"en":"Rice","fr":"Riz"},{"en":"Cabbage","fr":"Chou"},{"en":"Carrot","fr":"Carotte"},{"en":"Eggplant","fr":"Aubergine"},{"en":"Tomato","fr":"Tomate"},{"en":"Onion, garlic","fr":"Oignon, ail"},{"en":"Cooking oil","fr":"Huile de cuisson"}]'::jsonb, 'Fish is seasoned and browned, then simmered in a tomato-vegetable sauce; rice is cooked in the flavorful cooking liquid; vegetables are added toward the end.', 'Le poisson est assaisonné et doré, puis mijoté dans une sauce tomate-légumes ; le riz cuit dans le bouillon parfumé ; les légumes sont ajoutés en fin de cuisson.', '[{"en":"Prioritize the fish portion","fr":"Privilégier la portion de poisson"},{"en":"Increase the vegetables","fr":"Augmenter les légumes"},{"en":"Keep the rice portion moderate","fr":"Garder une portion de riz modérée"},{"en":"Use cooking oil in moderation","fr":"Utiliser l''huile avec modération"},{"en":"Reduce excess salt","fr":"Réduire l''excès de sel"},{"en":"Limit salty stock cubes/bouillon","fr":"Limiter les bouillons cubes salés"},{"en":"Choose water instead of sugary drinks","fr":"Choisir l''eau plutôt que des boissons sucrées"}]'::jsonb, '[{"en":"Salty bouillon cubes","fr":"Bouillons cubes salés"},{"en":"Excess cooking oil","fr":"Excès d''huile de cuisson"}]'::jsonb, '[{"en":"Herbs, garlic, and pepper instead of extra bouillon cube","fr":"Herbes, ail et piment au lieu de bouillon cube supplémentaire"},{"en":"A smaller rice portion with extra vegetables","fr":"Une portion de riz plus petite avec plus de légumes"}]'::jsonb, 520, 32, 55, 16, 6, 3, 620, 'good_choice', 'Fish protein and vegetables in one plate; consider moderating oil and bouillon-cube salt.', 'Protéines de poisson et légumes dans une même assiette ; pensez à modérer l''huile et le sel du bouillon cube.', ARRAY['fish', 'vegetables', 'traditional', 'rice']::text[]),
  ('Yassa Poisson', 'Yassa Poisson', 'Fish marinated and cooked with onions and lemon.', 'Poisson mariné et cuit avec oignons et citron.', 'senegalese_west_african', 'dinner', '1 plate (~400 g)', '1 assiette (~400 g)', '[{"en":"Fish","fr":"Poisson"},{"en":"Onions (generous amount)","fr":"Oignons (quantité généreuse)"},{"en":"Lemon","fr":"Citron"},{"en":"Garlic, pepper, herbs","fr":"Ail, piment, herbes"},{"en":"Cooking oil","fr":"Huile de cuisson"},{"en":"Rice or vegetables, to serve","fr":"Riz ou légumes, pour accompagner"}]'::jsonb, 'Fish is marinated in lemon, onion, and seasonings, then grilled or pan-cooked and finished with the onion sauce.', 'Le poisson est mariné au citron, à l''oignon et aux épices, puis grillé ou saisi et terminé avec la sauce à l''oignon.', '[{"en":"Grill or bake the fish where practical","fr":"Griller ou cuire au four le poisson quand c''est possible"},{"en":"Use a generous amount of onions and vegetables","fr":"Utiliser une quantité généreuse d''oignons et de légumes"},{"en":"Use cooking oil in moderation","fr":"Utiliser l''huile avec modération"},{"en":"Keep salt moderate","fr":"Garder le sel modéré"},{"en":"Lean on lemon and herbs for flavor","fr":"Miser sur le citron et les herbes pour la saveur"}]'::jsonb, '[{"en":"Excess oil in the marinade","fr":"Excès d''huile dans la marinade"},{"en":"Added salt","fr":"Sel ajouté"}]'::jsonb, '[{"en":"Grilled instead of fried fish","fr":"Poisson grillé plutôt que frit"}]'::jsonb, 480, 30, 45, 18, 4, 5, 550, 'best_choice', 'High-quality fish protein, generous vegetables, and citrus flavor that reduces the need for added salt.', 'Protéines de poisson de qualité, légumes généreux et saveur citronnée qui réduit le besoin de sel ajouté.', ARRAY['fish', 'vegetables', 'traditional']::text[]),
  ('Thiéré', 'Thiéré', 'Millet couscous served with vegetables and fish or chicken.', 'Couscous de mil servi avec légumes et poisson ou poulet.', 'senegalese_west_african', 'lunch', '1 plate (~420 g)', '1 assiette (~420 g)', '[{"en":"Millet couscous","fr":"Couscous de mil"},{"en":"Fish or chicken","fr":"Poisson ou poulet"},{"en":"Cabbage, carrot, squash","fr":"Chou, carotte, courge"},{"en":"Onion, garlic","fr":"Oignon, ail"},{"en":"Cooking oil","fr":"Huile de cuisson"}]'::jsonb, 'Millet couscous is steamed; fish or chicken and vegetables are cooked in a light sauce and served together.', 'Le couscous de mil est cuit à la vapeur ; le poisson ou le poulet et les légumes cuisent dans une sauce légère et sont servis ensemble.', '[{"en":"Emphasize the vegetables","fr":"Mettre l''accent sur les légumes"},{"en":"Choose fish or a lean protein","fr":"Choisir du poisson ou une protéine maigre"},{"en":"Use cooking oil in moderation","fr":"Utiliser l''huile avec modération"},{"en":"Keep salt moderate","fr":"Garder le sel modéré"},{"en":"Use millet as the whole-grain base","fr":"Utiliser le mil comme base de céréale complète"}]'::jsonb, '[{"en":"Excess oil in the sauce","fr":"Excès d''huile dans la sauce"},{"en":"Salty bouillon cubes","fr":"Bouillons cubes salés"}]'::jsonb, '[{"en":"Fonio in place of millet for variety","fr":"Fonio à la place du mil pour varier"}]'::jsonb, 460, 28, 58, 12, 7, 3, 480, 'good_choice', 'Whole-grain millet, vegetables, and a lean protein option; consider moderating oil and salt.', 'Mil complet, légumes et une option de protéine maigre ; pensez à modérer l''huile et le sel.', ARRAY['whole_grain', 'fish', 'vegetables', 'traditional']::text[]),
  ('Fonio, Vegetables & Fish', 'Fonio, légumes et poisson', 'A fonio-based plate emphasizing vegetables and fish.', 'Une assiette à base de fonio, avec légumes et poisson en avant.', 'senegalese_west_african', 'dinner', '1 plate (~400 g)', '1 assiette (~400 g)', '[{"en":"Fonio","fr":"Fonio"},{"en":"Fish","fr":"Poisson"},{"en":"Mixed vegetables (okra, tomato, leafy greens)","fr":"Légumes mélangés (gombo, tomate, légumes-feuilles)"},{"en":"Onion, garlic, pepper","fr":"Oignon, ail, piment"},{"en":"Cooking oil","fr":"Huile de cuisson"}]'::jsonb, 'Fonio is steamed until light and fluffy; fish and vegetables are prepared in a light sauce and served alongside.', 'Le fonio est cuit à la vapeur jusqu''à devenir léger ; le poisson et les légumes sont préparés dans une sauce légère et servis à côté.', '[{"en":"Prioritize vegetables","fr":"Privilégier les légumes"},{"en":"Prioritize fish","fr":"Privilégier le poisson"},{"en":"Keep the fonio portion moderate","fr":"Garder une portion de fonio modérée"},{"en":"Use cooking oil in moderation","fr":"Utiliser l''huile avec modération"},{"en":"Keep salt moderate","fr":"Garder le sel modéré"}]'::jsonb, '[{"en":"Excess oil","fr":"Excès d''huile"}]'::jsonb, '[{"en":"Millet in place of fonio","fr":"Mil à la place du fonio"}]'::jsonb, 420, 30, 48, 10, 6, 2, 420, 'best_choice', 'Whole-grain fonio, lean fish, and a vegetable-forward preparation that''s naturally lighter on oil.', 'Fonio complet, poisson maigre et préparation riche en légumes, naturellement plus légère en huile.', ARRAY['whole_grain', 'fish', 'vegetables']::text[]),
  ('Niébé (Black-Eyed Peas)', 'Niébé (haricots à œil noir)', 'A high-fiber plant-protein bean dish.', 'Un plat de haricots riche en fibres et en protéines végétales.', 'senegalese_west_african', 'dinner', '1 bowl (~350 g)', '1 bol (~350 g)', '[{"en":"Niébé (black-eyed peas)","fr":"Niébé (haricots à œil noir)"},{"en":"Tomato, onion, garlic","fr":"Tomate, oignon, ail"},{"en":"Mixed vegetables","fr":"Légumes mélangés"},{"en":"Cooking oil","fr":"Huile de cuisson"},{"en":"Herbs and spices","fr":"Herbes et épices"}]'::jsonb, 'Beans are simmered with tomato, onion, and vegetables until tender.', 'Les haricots mijotent avec tomate, oignon et légumes jusqu''à tendreté.', '[{"en":"Let the beans be the star, with generous vegetables","fr":"Laisser les haricots à l''honneur, avec des légumes généreux"},{"en":"Use cooking oil in moderation","fr":"Utiliser l''huile avec modération"},{"en":"Keep salt moderate","fr":"Garder le sel modéré"},{"en":"Season with herbs and spices rather than extra bouillon","fr":"Assaisonner avec des herbes et épices plutôt qu''un bouillon supplémentaire"}]'::jsonb, '[{"en":"Salty bouillon cubes","fr":"Bouillons cubes salés"}]'::jsonb, '[{"en":"Lentils for a quicker-cooking alternative","fr":"Lentilles pour une alternative à cuisson plus rapide"}]'::jsonb, 380, 18, 55, 8, 14, 4, 380, 'best_choice', 'High-fiber plant protein that''s naturally low in sodium and sugar when prepared simply.', 'Protéine végétale riche en fibres, naturellement faible en sodium et en sucre lorsqu''elle est préparée simplement.', ARRAY['legume', 'high_fiber', 'plant_protein']::text[]),
  ('Lentils with Vegetables', 'Lentilles aux légumes', 'Lentils simmered with vegetables, herbs, and spices.', 'Lentilles mijotées avec légumes, herbes et épices.', 'senegalese_west_african', 'dinner', '1 bowl (~350 g)', '1 bol (~350 g)', '[{"en":"Lentils","fr":"Lentilles"},{"en":"Tomato, onion, garlic","fr":"Tomate, oignon, ail"},{"en":"Mixed vegetables","fr":"Légumes mélangés"},{"en":"Herbs and spices","fr":"Herbes et épices"},{"en":"A small amount of cooking oil","fr":"Un peu d''huile de cuisson"}]'::jsonb, 'Lentils are simmered with aromatics and vegetables until soft.', 'Les lentilles mijotent avec des aromates et des légumes jusqu''à devenir tendres.', '[{"en":"Prioritize lentils and vegetables","fr":"Privilégier les lentilles et les légumes"},{"en":"Season generously with herbs and spices","fr":"Assaisonner généreusement avec herbes et épices"},{"en":"Keep sodium moderate","fr":"Garder le sodium modéré"}]'::jsonb, '[{"en":"Salty bouillon cubes","fr":"Bouillons cubes salés"}]'::jsonb, '[{"en":"Niébé (black-eyed peas) in place of lentils","fr":"Niébé à la place des lentilles"}]'::jsonb, 360, 20, 52, 6, 15, 3, 350, 'best_choice', 'Very high in fiber and plant protein, with low sodium when herbs and spices replace bouillon.', 'Très riche en fibres et en protéines végétales, avec un sodium faible lorsque herbes et épices remplacent le bouillon.', ARRAY['legume', 'high_fiber', 'plant_protein']::text[]),
  ('Soupe Kandia', 'Soupe Kandia', 'Okra-based soup, traditionally served over rice.', 'Soupe à base de gombo, traditionnellement servie avec du riz.', 'senegalese_west_african', 'dinner', '1 bowl with rice (~400 g)', '1 bol avec riz (~400 g)', '[{"en":"Okra","fr":"Gombo"},{"en":"Fish or meat","fr":"Poisson ou viande"},{"en":"Palm oil or cooking oil","fr":"Huile de palme ou huile de cuisson"},{"en":"Tomato, onion, garlic","fr":"Tomate, oignon, ail"},{"en":"Rice, to serve","fr":"Riz, pour accompagner"}]'::jsonb, 'Okra is cooked down into a thick sauce with fish or meat, then served over rice.', 'Le gombo est cuit jusqu''à former une sauce épaisse avec du poisson ou de la viande, puis servi avec du riz.', '[{"en":"Use oil in moderation","fr":"Utiliser l''huile avec modération"},{"en":"Keep sodium moderate","fr":"Garder le sodium modéré"},{"en":"Watch the portion size","fr":"Surveiller la taille de la portion"},{"en":"Choose a lean protein where possible","fr":"Choisir une protéine maigre si possible"},{"en":"Add extra vegetables","fr":"Ajouter des légumes supplémentaires"}]'::jsonb, '[{"en":"Excess palm oil","fr":"Excès d''huile de palme"},{"en":"Salty bouillon cubes","fr":"Bouillons cubes salés"}]'::jsonb, '[{"en":"A smaller amount of oil, with herbs and spices for flavor","fr":"Une quantité d''huile réduite, avec herbes et épices pour la saveur"}]'::jsonb, 430, 26, 40, 18, 6, 3, 550, 'moderation', 'Nutrient-dense, but traditionally higher in oil and sodium — enjoy with attention to portion and oil amount.', 'Nutritif, mais traditionnellement plus riche en huile et en sodium — à apprécier en portant attention à la portion et à l''huile.', ARRAY['fish', 'vegetables', 'traditional']::text[]),
  ('Mafé (lighter version)', 'Mafé (version allégée)', 'Peanut sauce stew, adapted with more vegetables and a moderate sauce portion.', 'Ragoût à la sauce d''arachide, adapté avec plus de légumes et une portion de sauce modérée.', 'senegalese_west_african', 'lunch', '1 plate (~420 g)', '1 assiette (~420 g)', '[{"en":"Peanut paste","fr":"Pâte d''arachide"},{"en":"Lean protein (chicken or fish)","fr":"Protéine maigre (poulet ou poisson)"},{"en":"Carrot, cabbage, squash","fr":"Carotte, chou, courge"},{"en":"Tomato, onion, garlic","fr":"Tomate, oignon, ail"},{"en":"Rice, to serve","fr":"Riz, pour accompagner"}]'::jsonb, 'Peanut paste is simmered into a sauce with tomato and protein; vegetables are added generously; served with rice.', 'La pâte d''arachide est mijotée en sauce avec tomate et protéine ; les légumes sont ajoutés généreusement ; servi avec du riz.', '[{"en":"Use a reasonable peanut-sauce portion","fr":"Utiliser une portion raisonnable de sauce d''arachide"},{"en":"Add more vegetables","fr":"Ajouter plus de légumes"},{"en":"Choose a lean protein","fr":"Choisir une protéine maigre"},{"en":"Keep the rice portion moderate","fr":"Garder une portion de riz modérée"},{"en":"Use oil in moderation (peanut paste already provides fat)","fr":"Utiliser l''huile avec modération (la pâte d''arachide apporte déjà du gras)"},{"en":"Keep salt moderate","fr":"Garder le sel modéré"}]'::jsonb, '[{"en":"A very large peanut-sauce portion","fr":"Une très grande portion de sauce d''arachide"},{"en":"Added oil on top of the peanut paste","fr":"Huile ajoutée en plus de la pâte d''arachide"}]'::jsonb, '[{"en":"Niébé or lentils in place of some of the peanut sauce for a lighter dish","fr":"Niébé ou lentilles à la place d''une partie de la sauce d''arachide pour un plat plus léger"}]'::jsonb, 500, 28, 48, 22, 7, 5, 500, 'moderation', 'Peanut sauce is calorie- and fat-dense; the lighter version with more vegetables and lean protein is better balanced, and portion awareness still helps.', 'La sauce d''arachide est dense en calories et en gras ; la version allégée avec plus de légumes et une protéine maigre est plus équilibrée, et l''attention à la portion reste utile.', ARRAY['peanut', 'traditional', 'vegetables']::text[]),
  ('Yassa Poulet', 'Yassa Poulet', 'Chicken marinated and cooked with onions and lemon.', 'Poulet mariné et cuit avec oignons et citron.', 'senegalese_west_african', 'lunch', '1 plate (~420 g)', '1 assiette (~420 g)', '[{"en":"Chicken (skin removed where practical)","fr":"Poulet (peau retirée si possible)"},{"en":"Onions (generous amount)","fr":"Oignons (quantité généreuse)"},{"en":"Lemon","fr":"Citron"},{"en":"Garlic, pepper, herbs","fr":"Ail, piment, herbes"},{"en":"Cooking oil","fr":"Huile de cuisson"},{"en":"Rice or vegetables, to serve","fr":"Riz ou légumes, pour accompagner"}]'::jsonb, 'Chicken is marinated in lemon, onion, and seasonings, then cooked and finished with the onion sauce.', 'Le poulet est mariné au citron, à l''oignon et aux épices, puis cuit et terminé avec la sauce à l''oignon.', '[{"en":"Choose lean chicken (remove skin where practical)","fr":"Choisir un poulet maigre (retirer la peau si possible)"},{"en":"Use a generous amount of onions and vegetables","fr":"Utiliser une quantité généreuse d''oignons et de légumes"},{"en":"Use cooking oil in moderation","fr":"Utiliser l''huile avec modération"},{"en":"Keep salt moderate","fr":"Garder le sel modéré"}]'::jsonb, '[{"en":"Chicken skin and excess oil","fr":"Peau de poulet et excès d''huile"}]'::jsonb, '[{"en":"Fish (Yassa Poisson) for variety","fr":"Poisson (Yassa Poisson) pour varier"}]'::jsonb, 460, 32, 42, 16, 4, 5, 520, 'good_choice', 'Lean chicken, generous vegetables, and citrus-forward flavor; choosing lean cuts keeps it lighter.', 'Poulet maigre, légumes généreux et saveur citronnée ; choisir des morceaux maigres allège le plat.', ARRAY['chicken', 'vegetables', 'traditional']::text[]),
  ('Lakh (lower-sugar)', 'Lakh (moins sucré)', 'Millet porridge with a reduced amount of added sugar.', 'Bouillie de mil avec une quantité réduite de sucre ajouté.', 'senegalese_west_african', 'breakfast', '1 bowl (~300 g)', '1 bol (~300 g)', '[{"en":"Millet flour","fr":"Farine de mil"},{"en":"Milk or yogurt","fr":"Lait ou yaourt"},{"en":"A small amount of sugar","fr":"Un peu de sucre"},{"en":"Fresh fruit, to serve","fr":"Fruit frais, pour accompagner"}]'::jsonb, 'Millet is cooked into a smooth porridge and served with milk or yogurt.', 'Le mil est cuit en une bouillie lisse et servi avec du lait ou du yaourt.', '[{"en":"Use noticeably less added sugar than the traditional preparation","fr":"Utiliser nettement moins de sucre ajouté que la préparation traditionnelle"},{"en":"Add fresh fruit for natural sweetness","fr":"Ajouter du fruit frais pour une douceur naturelle"},{"en":"Choose plain yogurt over sweetened yogurt","fr":"Choisir un yaourt nature plutôt qu''un yaourt sucré"}]'::jsonb, '[{"en":"Added sugar","fr":"Sucre ajouté"},{"en":"Sweetened condensed milk","fr":"Lait concentré sucré"}]'::jsonb, '[{"en":"Fresh fruit in place of some of the added sugar","fr":"Fruit frais à la place d''une partie du sucre ajouté"}]'::jsonb, 280, 9, 45, 6, 4, 8, 60, 'good_choice', 'A whole-grain millet base; choosing the lower-sugar preparation keeps free sugar in check.', 'Une base de mil complet ; choisir la préparation moins sucrée permet de limiter les sucres libres.', ARRAY['whole_grain', 'breakfast', 'lower_sugar']::text[]),
  ('Thiakry (lower-sugar)', 'Thiakry (moins sucré)', 'Millet couscous with yogurt, with reduced added sugar.', 'Couscous de mil au yaourt, avec moins de sucre ajouté.', 'senegalese_west_african', 'snack', '1 bowl (~250 g)', '1 bol (~250 g)', '[{"en":"Millet couscous","fr":"Couscous de mil"},{"en":"Yogurt","fr":"Yaourt"},{"en":"A small amount of sugar","fr":"Un peu de sucre"},{"en":"Vanilla or citrus zest, optional","fr":"Vanille ou zeste d''agrume, en option"}]'::jsonb, 'Steamed millet couscous is mixed with yogurt and a small amount of sugar.', 'Le couscous de mil cuit à la vapeur est mélangé avec du yaourt et un peu de sucre.', '[{"en":"Use noticeably less added sugar than the traditional preparation","fr":"Utiliser nettement moins de sucre ajouté que la préparation traditionnelle"},{"en":"Use plain yogurt","fr":"Utiliser un yaourt nature"},{"en":"Flavor with vanilla or citrus zest instead of extra sugar","fr":"Parfumer avec de la vanille ou du zeste d''agrume plutôt qu''avec du sucre supplémentaire"}]'::jsonb, '[{"en":"Added sugar","fr":"Sucre ajouté"}]'::jsonb, '[{"en":"Fresh fruit mixed in for natural sweetness","fr":"Fruit frais mélangé pour une douceur naturelle"}]'::jsonb, 260, 8, 42, 5, 3, 10, 55, 'moderation', 'Traditionally sugar-heavy; the lower-sugar version is meaningfully better, and it''s still worth enjoying in moderation.', 'Traditionnellement riche en sucre ; la version moins sucrée est nettement meilleure, et elle reste à apprécier avec modération.', ARRAY['breakfast', 'snack', 'lower_sugar']::text[]),
  ('Ndambé', 'Ndambé', 'A bean (black-eyed pea) stew, often served with bread.', 'Un ragoût de haricots (niébé), souvent servi avec du pain.', 'senegalese_west_african', 'breakfast', '1 bowl with bread (~350 g)', '1 bol avec pain (~350 g)', '[{"en":"Niébé (black-eyed peas)","fr":"Niébé (haricots à œil noir)"},{"en":"Tomato, onion","fr":"Tomate, oignon"},{"en":"A small amount of oil","fr":"Un peu d''huile"},{"en":"Bread, to serve","fr":"Pain, pour accompagner"}]'::jsonb, 'Beans are simmered with tomato and onion until soft, then served with bread.', 'Les haricots mijotent avec tomate et oignon jusqu''à devenir tendres, puis sont servis avec du pain.', '[{"en":"Keep the bread portion moderate","fr":"Garder une portion de pain modérée"},{"en":"Keep the bean quantity generous — it''s the fiber-rich part of the meal","fr":"Garder une quantité de haricots généreuse — c''est la partie riche en fibres du repas"},{"en":"Use added oil sparingly","fr":"Utiliser l''huile ajoutée avec parcimonie"},{"en":"Keep salt moderate","fr":"Garder le sel modéré"}]'::jsonb, '[{"en":"A large bread portion","fr":"Une grande portion de pain"},{"en":"Added oil","fr":"Huile ajoutée"}]'::jsonb, '[{"en":"Whole-grain bread in place of white bread","fr":"Pain complet à la place du pain blanc"}]'::jsonb, 380, 15, 55, 10, 10, 3, 480, 'good_choice', 'Bean-based and high in fiber; watching the bread portion and added oil keeps it well balanced.', 'À base de haricots et riche en fibres ; surveiller la portion de pain et l''huile ajoutée garde ce plat équilibré.', ARRAY['legume', 'high_fiber', 'breakfast']::text[]),
  ('Sweet Potato, Fish & Vegetables', 'Patate douce, poisson et légumes', 'Sweet potato served with fish and vegetables, as an alternative to a large rice portion.', 'Patate douce servie avec poisson et légumes, comme alternative à une grande portion de riz.', 'senegalese_west_african', 'dinner', '1 plate (~400 g)', '1 assiette (~400 g)', '[{"en":"Sweet potato","fr":"Patate douce"},{"en":"Fish","fr":"Poisson"},{"en":"Mixed vegetables","fr":"Légumes mélangés"},{"en":"Onion, garlic, herbs","fr":"Oignon, ail, herbes"},{"en":"A small amount of cooking oil","fr":"Un peu d''huile de cuisson"}]'::jsonb, 'Sweet potato is boiled, roasted, or steamed; fish and vegetables are prepared with light seasoning and served alongside.', 'La patate douce est bouillie, rôtie ou cuite à la vapeur ; le poisson et les légumes sont préparés avec un assaisonnement léger et servis à côté.', '[{"en":"Use sweet potato in place of a large rice portion","fr":"Utiliser la patate douce à la place d''une grande portion de riz"},{"en":"Add generous vegetables","fr":"Ajouter des légumes généreux"},{"en":"Choose a lean fish preparation","fr":"Choisir une préparation de poisson maigre"},{"en":"Use cooking oil in moderation","fr":"Utiliser l''huile avec modération"}]'::jsonb, '[{"en":"Added oil","fr":"Huile ajoutée"}]'::jsonb, '[{"en":"Fonio or millet in place of sweet potato for variety","fr":"Fonio ou mil à la place de la patate douce pour varier"}]'::jsonb, 400, 28, 42, 12, 6, 8, 380, 'best_choice', 'A whole-food, fiber-rich alternative to a large refined-starch portion, paired with lean fish protein.', 'Une alternative riche en fibres à une grande portion d''amidon raffiné, accompagnée de protéines de poisson maigres.', ARRAY['fish', 'vegetables', 'whole_food']::text[]),
  ('Ceebu Guinar', 'Ceebu Guinar', 'Chicken, rice, and vegetables simmered together — a poultry variation of Ceebu Jën.', 'Poulet, riz et légumes mijotés ensemble — une variante au poulet du Ceebu Jën.', 'senegalese_west_african', 'lunch', '1 plate (~450 g)', '1 assiette (~450 g)', '[{"en":"Chicken","fr":"Poulet"},{"en":"Rice","fr":"Riz"},{"en":"Cabbage, carrot, eggplant","fr":"Chou, carotte, aubergine"},{"en":"Tomato, onion, garlic","fr":"Tomate, oignon, ail"},{"en":"Cooking oil","fr":"Huile de cuisson"}]'::jsonb, 'Chicken is browned, then simmered in a tomato-vegetable sauce; rice is cooked in the flavorful cooking liquid.', 'Le poulet est doré, puis mijoté dans une sauce tomate-légumes ; le riz cuit dans le bouillon parfumé.', '[{"en":"Choose lean chicken (remove skin where practical)","fr":"Choisir un poulet maigre (retirer la peau si possible)"},{"en":"Increase the vegetables","fr":"Augmenter les légumes"},{"en":"Keep the rice portion moderate","fr":"Garder une portion de riz modérée"},{"en":"Use cooking oil in moderation","fr":"Utiliser l''huile avec modération"},{"en":"Limit salty stock cubes/bouillon","fr":"Limiter les bouillons cubes salés"}]'::jsonb, '[{"en":"Chicken skin","fr":"Peau de poulet"},{"en":"Salty bouillon cubes","fr":"Bouillons cubes salés"}]'::jsonb, '[{"en":"Fish (Ceebu Jën) for variety","fr":"Poisson (Ceebu Jën) pour varier"}]'::jsonb, 510, 30, 56, 15, 5, 3, 600, 'good_choice', 'A lean-poultry alternative to Ceebu Jën with the same vegetable-forward, moderate-rice approach.', 'Une alternative au poulet maigre du Ceebu Jën, avec la même approche riche en légumes et modérée en riz.', ARRAY['chicken', 'vegetables', 'traditional', 'rice']::text[]),
  ('Eggs, Whole-Grain Bread & Fruit', 'Œufs, pain complet et fruit', 'A simple protein-rich breakfast with whole-grain bread and fresh fruit.', 'Un petit-déjeuner simple et riche en protéines, avec pain complet et fruit frais.', 'senegalese_west_african', 'breakfast', '2 eggs + 1-2 slices bread + fruit', '2 œufs + 1-2 tranches de pain + fruit', '[{"en":"Eggs","fr":"Œufs"},{"en":"Whole-grain bread","fr":"Pain complet"},{"en":"Fresh fruit (or avocado)","fr":"Fruit frais (ou avocat)"},{"en":"A small amount of oil or butter","fr":"Un peu d''huile ou de beurre"}]'::jsonb, 'Eggs are cooked with a small amount of oil or butter and served with bread and fruit.', 'Les œufs sont cuits avec un peu d''huile ou de beurre et servis avec du pain et du fruit.', '[{"en":"Choose whole-grain bread for extra fiber","fr":"Choisir du pain complet pour plus de fibres"},{"en":"Use a small amount of oil or butter for cooking","fr":"Utiliser peu d''huile ou de beurre pour la cuisson"},{"en":"Add fresh fruit or avocado for variety","fr":"Ajouter du fruit frais ou de l''avocat pour varier"}]'::jsonb, '[{"en":"Excess butter or oil","fr":"Excès de beurre ou d''huile"}]'::jsonb, '[{"en":"Avocado in place of butter","fr":"Avocat à la place du beurre"}]'::jsonb, 350, 18, 38, 14, 5, 8, 380, 'good_choice', 'A simple, protein-rich breakfast; whole-grain bread adds fiber that white bread doesn''t.', 'Un petit-déjeuner simple et riche en protéines ; le pain complet ajoute des fibres que le pain blanc n''apporte pas.', ARRAY['breakfast', 'eggs']::text[])
) as v(name_en, name_fr, description_en, description_fr, cuisine, meal_type, serving_size_en, serving_size_fr, ingredients, preparation_en, preparation_fr, liver_conscious_preparation, foods_to_reduce, substitutions, calories_kcal, protein_g, carbs_g, fat_g, fiber_g, sugar_g, sodium_mg, rating, rating_reason_en, rating_reason_fr, tags)
where not exists (select 1 from meals existing where existing.name_en = v.name_en);

-- Resolve suggested_swap_meal_ids from the slug->name_en mapping above
-- (swaps are stored as an array of ids, but seed data can only refer
-- to other meals by name at insert time).
update meals set suggested_swap_meal_ids = (select coalesce(array_agg(id), '{}') from meals where name_en in ('Thiéré', 'Fonio, Vegetables & Fish', 'Yassa Poisson')) where name_en = 'Ceebu Jën';
update meals set suggested_swap_meal_ids = (select coalesce(array_agg(id), '{}') from meals where name_en in ('Yassa Poulet', 'Ceebu Jën', 'Sweet Potato, Fish & Vegetables')) where name_en = 'Yassa Poisson';
update meals set suggested_swap_meal_ids = (select coalesce(array_agg(id), '{}') from meals where name_en in ('Fonio, Vegetables & Fish', 'Ceebu Jën', 'Yassa Poisson')) where name_en = 'Thiéré';
update meals set suggested_swap_meal_ids = (select coalesce(array_agg(id), '{}') from meals where name_en in ('Thiéré', 'Sweet Potato, Fish & Vegetables', 'Ceebu Jën')) where name_en = 'Fonio, Vegetables & Fish';
update meals set suggested_swap_meal_ids = (select coalesce(array_agg(id), '{}') from meals where name_en in ('Lentils with Vegetables', 'Ndambé', 'Thiéré')) where name_en = 'Niébé (Black-Eyed Peas)';
update meals set suggested_swap_meal_ids = (select coalesce(array_agg(id), '{}') from meals where name_en in ('Niébé (Black-Eyed Peas)', 'Fonio, Vegetables & Fish', 'Sweet Potato, Fish & Vegetables')) where name_en = 'Lentils with Vegetables';
update meals set suggested_swap_meal_ids = (select coalesce(array_agg(id), '{}') from meals where name_en in ('Ceebu Jën', 'Fonio, Vegetables & Fish', 'Lentils with Vegetables')) where name_en = 'Soupe Kandia';
update meals set suggested_swap_meal_ids = (select coalesce(array_agg(id), '{}') from meals where name_en in ('Niébé (Black-Eyed Peas)', 'Lentils with Vegetables', 'Yassa Poulet')) where name_en = 'Mafé (lighter version)';
update meals set suggested_swap_meal_ids = (select coalesce(array_agg(id), '{}') from meals where name_en in ('Yassa Poisson', 'Mafé (lighter version)', 'Ceebu Guinar')) where name_en = 'Yassa Poulet';
update meals set suggested_swap_meal_ids = (select coalesce(array_agg(id), '{}') from meals where name_en in ('Thiakry (lower-sugar)', 'Eggs, Whole-Grain Bread & Fruit')) where name_en = 'Lakh (lower-sugar)';
update meals set suggested_swap_meal_ids = (select coalesce(array_agg(id), '{}') from meals where name_en in ('Lakh (lower-sugar)', 'Eggs, Whole-Grain Bread & Fruit')) where name_en = 'Thiakry (lower-sugar)';
update meals set suggested_swap_meal_ids = (select coalesce(array_agg(id), '{}') from meals where name_en in ('Niébé (Black-Eyed Peas)', 'Eggs, Whole-Grain Bread & Fruit')) where name_en = 'Ndambé';
update meals set suggested_swap_meal_ids = (select coalesce(array_agg(id), '{}') from meals where name_en in ('Fonio, Vegetables & Fish', 'Yassa Poisson', 'Thiéré')) where name_en = 'Sweet Potato, Fish & Vegetables';
update meals set suggested_swap_meal_ids = (select coalesce(array_agg(id), '{}') from meals where name_en in ('Ceebu Jën', 'Yassa Poulet', 'Thiéré')) where name_en = 'Ceebu Guinar';
update meals set suggested_swap_meal_ids = (select coalesce(array_agg(id), '{}') from meals where name_en in ('Lakh (lower-sugar)', 'Thiakry (lower-sugar)')) where name_en = 'Eggs, Whole-Grain Bread & Fruit';

notify pgrst, 'reload schema';
